solution:
ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
VALUE_OF = {digit: value for value, digit in enumerate(ALPHABET)}


def encode_base62(n):
    if n == 0:
        return ALPHABET[0]                      # the loop below would produce no digits at all
    digits = []
    while n:
        n, remainder = divmod(n, 62)
        digits.append(ALPHABET[remainder])      # least significant digit first...
    return "".join(reversed(digits))            # ...so reverse at the end


def decode_base62(text):
    if not text:
        raise ValueError("a code cannot be empty")
    n = 0
    for character in text:
        if character not in VALUE_OF:
            raise ValueError(f"{character!r} is not a base62 digit")
        n = n * 62 + VALUE_OF[character]        # shift what we have by one digit and add the next
    return n
